import Foundation

/// ノーツサウンド(キー音)の波形データ。KeySound.swift が起動時に読み込む。
///
/// - 元の音: 添付された 4 つの ogg (hit.ogg / hit-1.ogg / hit-2.ogg / sample-normal.ogg。どれも 44.1kHz)。
///   SETTING の「ノーツサウンドの種類」で選ぶ。音声ファイルはアプリに入れず、波形をここに埋め込んでいる
///   (Swift Playgrounds でも、.swift をコピーするだけで動くように)。
/// - 加工: ogg を 16bit PCM にほどいたもの (stb_vorbis。アプリ内のデコーダーと同じ)。
///   無音になっている末尾を切り落とし、末尾の急な切れ目 (プツッというノイズの原因) を 8ms のなめらかなフェードにした。
///   音量・音色はそのまま (音量をそろえたり、EQ をかけたりはしていない)。
/// - 形式: 44.1kHz / 16bit PCM (リトルエンディアン) を base64 にしたもの。
///   channels = 1 はモノラル、channels = 2 は左右 (L, R, L, R, ...) を交互に並べたステレオ。
///   sample-normal は元がほぼ左右同じ (左右の差が -47dB) なのでモノラルで持っている。
/// - 音を替えたい / 足したいときは、同じ形式の base64 に置き換え、NoteSoundKind (KeySound.swift) に項目を足せばよい。
enum KeySoundData {
    static let sampleRate: Double = 44100

    /// 1 種類ぶんの波形
    struct Wave {
        let channels: Int
        let pcm16Base64: String
    }

    static func wave(for kind: NoteSoundKind) -> Wave {
        switch kind {
        case .hit: return hit
        case .hit1: return hit1
        case .hit2: return hit2
        case .sampleNormal: return sampleNormal
        }
    }

